const rows = $input.all().map(i => i.json).filter(r => Object.keys(r).length > 0);
const form = $('Teacher Upload Form').first().json;
const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const norm = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
if (rows.length === 0) throw new Error('The Excel file has no student rows.');

const headers = Object.keys(rows[0]);
const find = test => headers.find(h => test(norm(h)));
const nameCol = find(h => h.includes('name'));
const rollCol = find(h => h.includes('roll'));
const emailCol = find(h => h.includes('email') || h.includes('mail'));
if (!nameCol || !rollCol || !emailCol) throw new Error('Excel must have Name, Roll Number and Email columns. Found: ' + headers.join(', '));
const subjects = headers.filter(h => h !== nameCol && h !== rollCol && h !== emailCol && String(h).trim() !== '');

const colors = ['#e8f0fe', '#fff4e5', '#e6f6ec', '#fdeaf1', '#f1ebfd'];
const out = [];
for (const r of rows) {
  const name = String(r[nameCol] ?? '').trim();
  const roll = String(r[rollCol] ?? '').trim();
  const email = String(r[emailCol] ?? '').trim();
  let problem = '';
  if (!name) problem = 'Missing name';
  else if (!roll) problem = 'Missing roll number';
  else if (!email) problem = 'Missing email';
  else if (!emailRe.test(email)) problem = 'Invalid email: ' + email;
  if (problem) { out.push({ json: { valid: false, studentName: name, rollNumber: roll, email, reason: problem } }); continue; }
  const tr = subjects.map((s, idx) => {
    const v = r[s];
    const mark = (v === undefined || v === null || String(v).trim() === '') ? '-' : String(v);
    return '<tr style="background:' + colors[idx % colors.length] + ';"><td style="padding:10px 14px;border:1px solid #d0d7e2;">' + esc(s) + '</td><td style="padding:10px 14px;border:1px solid #d0d7e2;text-align:center;font-weight:bold;color:#1a237e;">' + esc(mark) + '</td></tr>';
  }).join('');
  const html = '<div style="font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:auto;border:1px solid #d0d7e2;border-radius:10px;overflow:hidden;">'
    + '<div style="background:linear-gradient(90deg,#3949ab,#8e24aa);padding:24px;color:#ffffff;text-align:center;"><h1 style="margin:0;font-size:24px;">Student Result Report</h1></div>'
    + '<div style="padding:24px;background:#ffffff;">'
    + '<p style="font-size:16px;color:#333;">Dear <b>' + esc(name) + '</b>,</p>'
    + '<p style="color:#555;">Here are your results.</p>'
    + '<p style="color:#333;"><b>Name:</b> ' + esc(name) + '<br><b>Roll Number:</b> ' + esc(roll) + '</p>'
    + '<table style="border-collapse:collapse;width:100%;margin-top:12px;"><tr style="background:#3949ab;color:#ffffff;"><th style="padding:10px 14px;text-align:left;border:1px solid #3949ab;">Subject</th><th style="padding:10px 14px;border:1px solid #3949ab;">Marks</th></tr>' + tr + '</table>'
    + '</div><div style="background:#f5f5f5;padding:12px;text-align:center;color:#888;font-size:12px;">This is an automated result report.</div></div>';
  out.push({ json: { valid: true, studentName: name, rollNumber: roll, email, sendTo: email, subject: 'Result Report - ' + name + ' (Roll ' + roll + ')', html } });
}
return out;

const items = $input.all().map(i => i.json);
const sent = items.filter(i => i.status === 'SENT');
const failed = items.filter(i => i.status === 'EMAIL FAILED');
const skipped = items.filter(i => i.status === 'SKIPPED');
const form = $('Teacher Upload Form').first().json;
const teacherEmail = String(form['teacher_email'] || '').trim();
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const list = (arr, fn) => arr.length ? '<ul style="margin:6px 0 0 18px;padding:0;color:#444;">' + arr.map(a => '<li>' + esc(fn(a)) + '</li>').join('') + '</ul>' : '';
const card = (n, label, color) => '<td style="width:33%;padding:6px;"><div style="background:' + color + ';border-radius:8px;padding:16px;text-align:center;color:#ffffff;"><div style="font-size:30px;font-weight:bold;">' + n + '</div><div style="font-size:13px;">' + label + '</div></div></td>';
let html = '<div style="font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:auto;border:1px solid #d0d7e2;border-radius:10px;overflow:hidden;">'
  + '<div style="background:linear-gradient(90deg,#00897b,#3949ab);padding:24px;color:#ffffff;text-align:center;"><h1 style="margin:0;font-size:24px;">Sending Completed</h1></div>'
  + '<div style="padding:24px;background:#ffffff;">'
  + '<p style="font-size:16px;color:#333;">Hello,</p>'
  + '<p style="color:#555;">' + 'All student result emails have been processed. Here is the summary:</p>'
  + '<table style="width:100%;border-collapse:collapse;"><tr>' + card(sent.length, 'Sent successfully', '#43a047') + card(failed.length, 'Failed', '#e53935') + card(skipped.length, 'Skipped (invalid data)', '#fb8c00') + '</tr></table>';
if (failed.length) html += '<h3 style="color:#e53935;margin-bottom:0;">Failed emails</h3>' + list(failed, f => f.student + ' - ' + f.error);
if (skipped.length) html += '<h3 style="color:#fb8c00;margin-bottom:0;">Skipped rows</h3>' + list(skipped, f => f.student + ' - ' + f.reason);
html += '</div><div style="background:#f5f5f5;padding:12px;text-align:center;color:#888;font-size:12px;">Automated message from the Student Result workflow.</div></div>';
return [{ json: { teacherEmail, subject: 'Student Result Reports - Sending Completed', html, sentCount: sent.length, failedCount: failed.length } }];
